const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const selectedHook = String($json.selected_hook ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Publish Draft Item did not produce a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Publish Draft Item did not produce a title.');
}
if (!selectedHook) {
  throw new Error('Fetch Next Publish Draft Item did not produce a selected_hook.');
}
const narrationScript = String($json.narration_script ?? '').trim();
if (!narrationScript) {
  throw new Error('Fetch Next Publish Draft Item did not produce a narration_script.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    content_status: String($json.status ?? 'script_complete').trim() || 'script_complete',
    selected_hook: selectedHook,
    narration_script: narrationScript,
    caption_draft: String($json.caption_draft ?? '').trim(),
    cta_line: String($json.cta_line ?? '').trim(),
    cover_prompt: String($json.cover_prompt ?? '').trim(),
    existing_publish_status: String($json.existing_publish_status ?? 'draft').trim() || 'draft',
    brand_tone: 'cinematic, concise, credible',
    publish_status_after_success: 'draft',
    workflow_name: 'wf_caption_and_hashtags',
    run_started_at: new Date().toISOString()
  }
}];

if (!$json.content_id || !$json.openai_request_caption_first_pass) {
  throw new Error('Build Caption First Pass Request did not provide the expected OpenAI request payload.');
}
const apiKey = String($env.OPENAI_API_KEY || $env.LLL_API_KEY || '').trim();
if (!apiKey) {
  throw new Error('Set OPENAI_API_KEY in the repo-root .env before running wf_caption_and_hashtags. For backward compatibility, LLL_API_KEY is also accepted.');
}
const request = $json.openai_request_caption_first_pass;
if (!request.model) {
  throw new Error('No OpenAI model was configured for the caption workflow first pass.');
}
const response = await helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/chat/completions',
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  headers: {
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
  },
  body: {
    model: request.model,
    messages: request.messages,
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'caption_first_pass',
        schema: request.response_schema,
        strict: true
      }
    }
  }
});
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};
if (!(statusCode >= 200 && statusCode < 300) || body.error) {
  throw new Error('OpenAI caption first pass failed (' + (statusCode || 'no status') + '): ' + (body?.error?.message ?? 'unknown error'));
}
const content = body?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('OpenAI caption first pass returned no message content.');
}
let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('OpenAI caption first pass response was not valid JSON: ' + error.message);
}
return [{
  json: {
    ...$json,
    caption_first_pass_model: String(body.model ?? request.model),
    caption_first_pass_response: parsed,
    caption_first_pass_provider_metadata: {
      response_id: body.id ?? null,
      usage: body.usage ?? null,
      finish_reason: body?.choices?.[0]?.finish_reason ?? null
    }
  }
}];

const response = $json.caption_first_pass_response ?? {};
const requiredFields = [
  'caption_option_1',
  'caption_option_2',
  'caption_option_3',
  'selection_rationale',
  'caption_final'
];
for (const field of requiredFields) {
  if (!String(response[field] ?? '').trim()) {
    throw new Error('Call OpenAI Caption First Pass returned an empty ' + field + '.');
  }
}
return [{
  json: {
    ...$json,
    caption_option_1: String(response.caption_option_1).trim(),
    caption_option_2: String(response.caption_option_2).trim(),
    caption_option_3: String(response.caption_option_3).trim(),
    caption_selection_rationale: String(response.selection_rationale).trim(),
    first_pass_caption_recommendation: String(response.caption_final).trim()
  }
}];

if (!$json.content_id || !$json.openai_request_caption_final_pass) {
  throw new Error('Build Caption Final Pass Request did not provide the expected OpenAI request payload.');
}
const apiKey = String($env.OPENAI_API_KEY || $env.LLL_API_KEY || '').trim();
if (!apiKey) {
  throw new Error('Set OPENAI_API_KEY in the repo-root .env before running wf_caption_and_hashtags. For backward compatibility, LLL_API_KEY is also accepted.');
