    messages: request.messages,
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'caption_final_pass',
        schema: request.response_schema,
        strict: true
      }
    }
  }
});
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};
if (!(statusCode >= 200 && statusCode < 300) || body.error) {
  throw new Error('OpenAI caption final pass failed (' + (statusCode || 'no status') + '): ' + (body?.error?.message ?? 'unknown error'));
}
const content = body?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('OpenAI caption final pass returned no message content.');
}
let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('OpenAI caption final pass response was not valid JSON: ' + error.message);
}
return [{
  json: {
    ...$json,
    caption_final_pass_model: String(body.model ?? request.model),
    caption_final_pass_response: parsed,
    caption_final_pass_provider_metadata: {
      response_id: body.id ?? null,
      usage: body.usage ?? null,
      finish_reason: body?.choices?.[0]?.finish_reason ?? null
    }
  }
}];

const response = $json.caption_final_pass_response ?? {};
if (!String(response.revision_summary ?? '').trim()) {
  throw new Error('Call OpenAI Caption Final Pass returned an empty revision_summary.');
}
if (!String(response.caption_final ?? '').trim()) {
  throw new Error('Call OpenAI Caption Final Pass returned an empty caption_final.');
}
return [{
  json: {
    ...$json,
    caption_final: String(response.caption_final).trim(),
    revision_summary: String(response.revision_summary).trim()
  }
}];

if (!$json.content_id || !$json.openai_request_hashtag_ranking) {
  throw new Error('Build Hashtag Ranking Request did not provide the expected OpenAI request payload.');
}
const apiKey = String($env.OPENAI_API_KEY || $env.LLL_API_KEY || '').trim();
if (!apiKey) {
  throw new Error('Set OPENAI_API_KEY in the repo-root .env before running wf_caption_and_hashtags. For backward compatibility, LLL_API_KEY is also accepted.');
