    hashtag_ranking_response: parsed,
    hashtag_ranking_provider_metadata: {
      response_id: body.id ?? null,
      usage: body.usage ?? null,
      finish_reason: body?.choices?.[0]?.finish_reason ?? null
    }
  }
}];

const response = $json.hashtag_ranking_response ?? {};
const requiredFields = [
  'hashtag_set_1',
  'hashtag_set_2',
  'hashtag_set_3',
  'hashtag_selection_rationale',
  'hashtags_final'
];
for (const field of requiredFields) {
  if (!String(response[field] ?? '').trim()) {
    throw new Error('Call OpenAI Hashtag Ranking returned an empty ' + field + '.');
  }
}
const hashtagRankingJson = {
  provider: 'openai',
  model: String($json.hashtag_ranking_model ?? '').trim(),
  provider_metadata: $json.hashtag_ranking_provider_metadata ?? {},
  output: {
    hashtag_set_1: String(response.hashtag_set_1).trim(),
    hashtag_set_2: String(response.hashtag_set_2).trim(),
    hashtag_set_3: String(response.hashtag_set_3).trim(),
    hashtag_selection_rationale: String(response.hashtag_selection_rationale).trim(),
    hashtags_final: String(response.hashtags_final).trim()
  }
};
const captionIterationJson = {
  provider: 'openai',
  first_pass: {
    model: String($json.caption_first_pass_model ?? '').trim(),
    provider_metadata: $json.caption_first_pass_provider_metadata ?? {},
    output: {
      caption_option_1: $json.caption_option_1,
      caption_option_2: $json.caption_option_2,
      caption_option_3: $json.caption_option_3,
      selection_rationale: $json.caption_selection_rationale,
      caption_final: $json.first_pass_caption_recommendation
    }
  },
  final_pass: {
    model: String($json.caption_final_pass_model ?? '').trim(),
    provider_metadata: $json.caption_final_pass_provider_metadata ?? {},
    output: {
      revision_summary: $json.revision_summary,
      caption_final: $json.caption_final
    }
  }
};
return [{
  json: {
    content_id: $json.content_id,
    workflow_name: $json.workflow_name,
    run_started_at: $json.run_started_at,
    publish_status_after_success: $json.publish_status_after_success,
    caption_final: $json.caption_final,
    hashtags_final: String(response.hashtags_final).trim(),
    revision_summary: $json.revision_summary,
    hashtag_selection_rationale: String(response.hashtag_selection_rationale).trim(),
    generation_model: String($json.hashtag_ranking_model || $json.caption_final_pass_model || $json.caption_first_pass_model || '').trim(),
    caption_iteration_json: captionIterationJson,
    hashtag_ranking_json: hashtagRankingJson
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Publish Draft SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    caption_final_sql: String($json.caption_final ?? '').replaceAll("'", "''"),
    hashtags_final_sql: String($json.hashtags_final ?? '').replaceAll("'", "''"),
    publish_status_sql: String($json.publish_status_after_success ?? 'draft').replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_caption_and_hashtags').replaceAll("'", "''"),
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    revision_summary_sql: String($json.revision_summary ?? '').replaceAll("'", "''"),
    hashtag_selection_rationale_sql: String($json.hashtag_selection_rationale ?? '').replaceAll("'", "''"),
    caption_iteration_json_sql: JSON.stringify($json.caption_iteration_json ?? {}).replaceAll("'", "''"),
    hashtag_ranking_json_sql: JSON.stringify($json.hashtag_ranking_json ?? {}).replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0
  }
}];
